describe('Comment on Record Feature', () => {
  beforeEach(() => {
    cy.visit('/records');
    cy.intercept('GET', '/api/records/1').as('getRecord');
    cy.intercept('POST', '/api/records/1/comments').as('postComment');
    cy.get('[data-testid="record-1"]').should('be.visible');
  });

  it('should successfully add a comment to a record', () => {
    cy.wait('@getRecord');
    cy.get('[data-testid="comment-input"]').should('be.visible');
    cy.get('[data-testid="comment-input"]').type('This is a test comment');
    cy.get('[data-testid="submit-comment-btn"]').click();
    cy.wait('@postComment');
    cy.get('[data-testid="comment-list"]').should('be.visible');
    cy.get('[data-testid="comment-item"]').should('contain', 'This is a test comment');
    cy.get('[data-testid="comment-item"]').should('be.visible');
    cy.get('[data-testid="comment-count"]').should('contain', '1');
  });

  it('should display error message when submitting an empty comment', () => {
    cy.wait('@getRecord');
    cy.get('[data-testid="comment-input"]').should('be.visible');
    cy.get('[data-testid="comment-input"]').type(' ');
    cy.get('[data-testid="submit-comment-btn"]').click();
    cy.wait('@postComment');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Comment cannot be empty');
    cy.get('[data-testid="comment-item"]').should('not.exist');
  });
});
